const solid = c => [{type:"SOLID",color:c}];
async function T(chars, fam, style, size, color, opts={}){
  const t = figma.createText();
  t.fontName = {family:fam,style};
  t.characters = chars;
  t.fontSize = size;
  t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value:opts.lh,unit:"PIXELS"};
  if (opts.ls) t.letterSpacing = {value:opts.ls,unit:"PIXELS"};
  if (opts.name) t.name = opts.name;
  if (opts.width){ t.textAutoResize="HEIGHT"; t.resize(opts.width, t.height); }
  return t;
}
function auto(dir, gap, pad, align){
  const f = figma.createFrame();
  f.layoutMode = dir; f.itemSpacing = gap;
  if (pad){ f.paddingLeft=pad[0]; f.paddingRight=pad[1]; f.paddingTop=pad[2]; f.paddingBottom=pad[3]; }
  f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO";
  if (align) f.counterAxisAlignItems = align;
  f.fills=[];
  return f;
}
