const NAVS = ["Home","Blog","About Us","Contact us"];
function buildHeader(current){
  const h = figma.createFrame();
  h.name = "Current=" + (current||"None");
  h.layoutMode="HORIZONTAL"; h.counterAxisAlignItems="CENTER"; h.itemSpacing=40;
  h.paddingLeft=120; h.paddingRight=120; h.paddingTop=20; h.paddingBottom=20;
  h.primaryAxisSizingMode="FIXED"; h.counterAxisSizingMode="AUTO";
  h.resize(1440, h.height);
  h.fills = solid(C.ink);
  return h;
}
async function headerVariant(current){
  const h = buildHeader(current);
  // wordmark
  const wm = await T("{Inkline","Sen","Bold",28,C.white,{name:"Wordmark"});
  wm.setRangeFills(0,1,solid(C.yellow));
  h.appendChild(wm);
  h.appendChild(Object.assign(auto("HORIZONTAL",0,[0,0,0,0]),{layoutGrow:1}));
  const nav = auto("HORIZONTAL",32,[0,0,0,0],"CENTER");
  nav.name="Nav";
  for (const n of NAVS){
    const item = auto("VERTICAL",6,[0,0,0,0],"CENTER");
    item.name = "Nav "+n;
    const isCur = n===current;
    const t = await T(n,"Inter","Medium",16, isCur?C.yellow:C.white,{name:"Label"});
    item.appendChild(t);
    const bar = figma.createRectangle();
    bar.name="Underline"; bar.resize(24,2); bar.fills=solid(C.yellow);
    bar.visible = isCur;
    item.appendChild(bar);
    nav.appendChild(item);
