async function catIcon(cat, size, color){
  const src = await figma.getNodeByIdAsync(CAT_ICON_IDS[cat]);
  const inst = src.createInstance();
  inst.name = "Icon_Category_"+cat;
  const s = size / Math.max(inst.width, inst.height);
  inst.resize(Math.round(inst.width*s), Math.round(inst.height*s));
  if (color){
    const paint = solid(color);
    inst.findAll(n=>n.type==="VECTOR"||n.type==="GROUP"||n.type==="FRAME"||n.type==="BOOLEAN_OPERATION"||n.type==="INSTANCE").forEach(n=>{ try{ n.fills=paint; }catch(e){} });
    try{ inst.fills=paint; }catch(e){}
  }
  return inst;
}
