const C = {
  ink:{r:0.137,g:0.145,b:0.212}, inkSoft:{r:0.22,g:0.23,b:0.31},
  yellow:{r:1,g:0.816,b:0.314}, purple:{r:0.349,g:0.18,b:0.663},
  body:{r:0.427,g:0.431,b:0.463}, muted:{r:0.6,g:0.605,b:0.64},
  border:{r:0.89,g:0.89,b:0.91}, tint:{r:0.969,g:0.969,b:0.98},
  white:{r:1,g:1,b:1}, white70:{r:0.85,g:0.855,b:0.88}
};
const solid = c => [{type:"SOLID",color:c}];
async function T(chars, fam, style, size, color, opts={}){
  const t = figma.createText();
  t.fontName = {family:fam,style};
  t.characters = chars;
  t.fontSize = size;
  t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value:opts.lh,unit:"PIXELS"};
  if (opts.ls) t.letterSpacing = {value:opts.ls,unit:"PIXELS"};
  if (opts.name) t.name = opts.name;
  if (opts.width){ t.textAutoResize="HEIGHT"; t.resize(opts.width, t.height); }
  return t;
}
function sec(name, gap, padV, bg){
  const s = figma.createFrame();
  s.name=name;
  s.layoutMode="VERTICAL"; s.itemSpacing=gap;
  s.paddingLeft=120; s.paddingRight=120; s.paddingTop=padV; s.paddingBottom=padV;
  s.primaryAxisSizingMode="FIXED"; s.counterAxisSizingMode="AUTO";
  s.fills = bg?solid(bg):[];
  return s;
}
function row(gap, align){
  const r = figma.createFrame();
  r.layoutMode="HORIZONTAL"; r.itemSpacing=gap;
  r.primaryAxisSizingMode="AUTO"; r.counterAxisSizingMode="AUTO";
  if (align) r.counterAxisAlignItems=align;
  r.fills=[];
  return r;
}
async function link(label, name){
  return await T(label,"Inter","Semi Bold",15,C.purple,{name:name||"Link"});
}
const IDS = {header:"7:115", footer:"7:166", join:"7:174", pti:"8:43", cc:"8:76", ac:"8:141"};
const PHOTO_IDS = {Building:"1:225",GroupHero:"1:227",HomeHero:"1:228"};
async function photo(key,w,h,r){
  const src = await figma.getNodeByIdAsync(PHOTO_IDS[key]);
  const i = src.createInstance(); i.name="Photo_"+key; i.resize(w,h);
  if(r!==undefined) i.cornerRadius=r;
  return i;
}
const AV_IDS = {Andrew:"1:200",Jonathan:"1:207",Floyd:"1:203",Dianne:"1:201",Jenny:"1:206",Leslie:"1:208",Guy:"1:204",Eleanor:"1:202",Robert:"1:209",Jacob:"1:205"};
async function avatar(key,size){
  const src = await figma.getNodeByIdAsync(AV_IDS[key]);
  const i = src.createInstance(); i.name="Avatar_"+key; i.resize(size,size); i.cornerRadius=size/2;
  return i;
}
async function authorCard(nm, av, state){
  const acSet = await figma.getNodeByIdAsync(IDS.ac);
  const inst = acSet.defaultVariant.createInstance();
  inst.setProperties({"State":state});
  inst.findOne(n=>n.name==="Name").characters = nm;
  let idx = -1;
  for (let i=0;i<inst.children.length;i++){ if (inst.children[i].name.indexOf("Avatar")===0){ idx=i; break; } }
  const newAv = await avatar(av,88);
  if (idx>=0){
    inst.children[idx].visible = false;
    inst.insertChild(idx, newAv);
  } else {
    inst.appendChild(newAv);
  }
  return inst;
}

