const BLOCK = new Set(["Title","Excerpt","Quote","Sub","Body","Lead","Placeholder","Desc","Heading","NL Heading","Address","Contact","Text","Lead Line","Para"]);
let textFixed=0, spacerFixed=0;

function walk(n){
  if (n.type==="TEXT" && BLOCK.has(n.name)){
    const p = n.parent;
    if (p && p.layoutMode==="VERTICAL"){
      const cw = p.width - p.paddingLeft - p.paddingRight;
      if (Math.abs(n.width - cw) > 2 || n.textAutoResize!=="HEIGHT"){
        n.textAutoResize = "HEIGHT";
        n.resize(cw, n.height);
        textFixed++;
      }
    }
  }
  if (n.name==="Spacer" && n.parent && n.parent.layoutMode==="HORIZONTAL"){
    if (n.layoutGrow!==1){ n.layoutGrow=1; spacerFixed++; }
    if (n.height>1) n.resize(n.width,1);
  }
  if ("children" in n) for (const c of n.children) walk(c);
}
for (const top of page.children) walk(top);

