const solid = c => [{type:"SOLID",color:c}];
async function txt(chars, font, size, color, opts={}){
  const t = figma.createText();
  t.fontName = font; t.fontSize = size; t.characters = chars; t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value:opts.lh, unit:"PIXELS"};
  if (opts.ls) t.letterSpacing = {value:opts.ls, unit:"PIXELS"};
  if (opts.name) t.name = opts.name;
  return t;
}
const SEN={family:"Sen",style:"Bold"}, IR={family:"Inter",style:"Regular"}, IM={family:"Inter",style:"Medium"}, ISB={family:"Inter",style:"Semi Bold"};
function auto(name, dir, gap, pad){
  const f = figma.createFrame(); f.name=name; f.layoutMode=dir; f.itemSpacing=gap||0;
  if (pad){ f.paddingTop=pad[0]; f.paddingRight=pad[1]; f.paddingBottom=pad[2]; f.paddingLeft=pad[3]; }
  f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO"; f.fills=[];
  return f;
}
function section(name, bg, padV){
  const s = figma.createFrame(); s.name=name; s.layoutMode="VERTICAL"; s.itemSpacing=0;
  s.paddingTop=padV; s.paddingBottom=padV; s.paddingLeft=120; s.paddingRight=120;
  s.primaryAxisSizingMode="AUTO"; s.counterAxisSizingMode="FIXED"; s.resize(1440,100);
  s.fills = bg? solid(bg):[];
  return s;
}
function inner(name, gap){
  const f = auto(name,"VERTICAL",gap||0); f.layoutAlign="STRETCH"; return f;
}
async function media(id, w, h){
  const comp = await figma.getNodeByIdAsync(id);
  const inst = comp.createInstance();
  inst.resize(w,h);
  return inst;
}
