function dump(n, depth){
  if (depth>3) return null;
  const d = {name:n.name, w:Math.round(n.width), h:Math.round(n.height)};
  if (n.layoutMode){ d.lm=n.layoutMode[0]; d.pax=n.primaryAxisSizingMode[0]; d.cax=n.counterAxisSizingMode[0]; d.la=n.layoutAlign; d.lg=n.layoutGrow; }
  if (n.type==="TEXT") d.t=n.characters.slice(0,15);
  if ("children" in n && n.children.length && depth<3) d.k = n.children.map(c=>dump(c,depth+1)).filter(Boolean);
  return d;
}
