const report = {};
for (const nm of ["01_Home","02_Blog","03_Blog_Post"]){
  const screen = page.findOne(n=>n.name===nm);
  if (!screen) continue;
  let fixed = 0;
  for (const f of screen.findAll(n=>n.layoutMode==="HORIZONTAL" && n.layoutAlign==="STRETCH")){
    const parent = f.parent;
    if (!parent || !parent.width) continue;
    const targetW = parent.width - parent.paddingLeft - parent.paddingRight;
    if (Math.abs(f.width - targetW) > 2){
      f.primaryAxisSizingMode = "FIXED";
      f.resize(targetW, f.height);
      fixed++;
    }
  }
  report[nm] = {fixed, h: Math.round(screen.height), sections: screen.children.map(c=>c.name+":"+Math.round(c.height)).join(" | ")};
}
return JSON.stringify(report);

