function compByName(name){
  return page.findOne(n=>(n.type==="COMPONENT"||n.type==="COMPONENT_SET") && n.name===name);
}
function variantOf(setName, variantName){
  const set = compByName(setName);
  if (!set) throw new Error("set missing "+setName);
  if (set.type==="COMPONENT") return set;
  const v = set.children.find(c=>c.name===variantName);
  if (!v) throw new Error("variant missing "+setName+" / "+variantName+" have: "+set.children.map(c=>c.name).join(";"));
  return v;
}
function mediaComp(name){
  return mediaPage.findOne(n=>n.type==="COMPONENT" && n.name===name);
}
function makeScreen(name, x){
  const s = figma.createFrame();
  s.name=name;
  s.resize(1440, 900);
  s.layoutMode="VERTICAL"; s.itemSpacing=0;
  s.primaryAxisSizingMode="AUTO"; s.counterAxisSizingMode="FIXED";
  s.fills=[{type:"SOLID",color:WHITE}];
  s.clipsContent=true;
  page.appendChild(s);
  s.x=x; s.y=0;
  return s;
}
function section(name, pad, gap, bg){
  const f = figma.createFrame();
  f.name=name; f.layoutMode="VERTICAL"; f.itemSpacing=gap||0;
  f.paddingTop=pad[0]; f.paddingRight=pad[1]; f.paddingBottom=pad[2]; f.paddingLeft=pad[3];
  f.counterAxisSizingMode="FIXED"; f.primaryAxisSizingMode="AUTO";
  f.fills= bg? [{type:"SOLID",color:bg}] : [];
  f.resize(1440, 100);
  return f;
}
function inner(name, dir, gap){
  const f = autoFrame(name, dir, gap);
  return f;
}
function stretchRow(f, parentPadL, parentPadR){
  f.layoutAlign="STRETCH";
  f.primaryAxisSizingMode="FIXED";
  f.resize(1440-parentPadL-parentPadR, f.height);
  return f;
}

