  for (const f of screen.findAll(n=>n.layoutMode==="VERTICAL")){
    const parent = f.parent;
    if (!parent || !parent.layoutMode) continue;
    if (parent.layoutMode==="VERTICAL"){
      // direct child of screen or section: stretch to parent content width
      const targetW = parent.width - parent.paddingLeft - parent.paddingRight;
      if (targetW > 100 && Math.abs(f.width - targetW) > 2){
        f.counterAxisSizingMode="FIXED";
        f.primaryAxisSizingMode="AUTO";
        f.resize(targetW, f.height);
        f.layoutAlign="STRETCH";
      }
    } else if (parent.layoutMode==="HORIZONTAL"){
      // row child: keep as is unless it collapsed to <100 width with layoutGrow
      if (f.layoutGrow===1 && f.width < 200){
        f.counterAxisSizingMode="FIXED";
        f.primaryAxisSizingMode="AUTO";
      }
    }
  }
  // fix horizontal rows that are stretched: width fixed to parent content
  for (const f of screen.findAll(n=>n.layoutMode==="HORIZONTAL" && n.layoutAlign==="STRETCH")){
    const parent = f.parent;
    if (!parent || !parent.layoutMode) continue;
    const targetW = parent.width - parent.paddingLeft - parent.paddingRight;
    if (targetW > 100 && Math.abs(f.width - targetW) > 2){
      f.primaryAxisSizingMode="FIXED";
      f.resize(targetW, f.height);
    }
  }
  report[nm] = {h:Math.round(screen.height), sections: screen.children.map(c=>c.name+":"+Math.round(c.height)).join(" | ")};
}
