function hotspot(screen, target, to, name, pad){
  pad = pad || 4;
  const inv = screen.absoluteTransform;
  const a = inv[0][0], b = inv[0][1], tx = inv[0][2];
  const c = inv[1][0], d = inv[1][1], ty = inv[1][2];
  const det = a*d - b*c;
  const ia = d/det, ib = -b/det, ic = -c/det, id2 = a/det;
  const itx = (-d*tx + b*ty)/det, ity = (c*tx - a*ty)/det;
  const at = target.absoluteTransform;
  const w = target.width, h = target.height;
  const pts = [[0,0],[w,0],[0,h],[w,h]].map(([px,py])=>[at[0][2]+at[0][0]*px+at[0][1]*py, at[1][2]+at[1][0]*px+at[1][1]*py]);
  const xs = [], ys = [];
  for (const [X,Y] of pts){ xs.push(ia*X + ib*Y + itx); ys.push(ic*X + id2*Y + ity); }
  const x = Math.min(...xs)-pad, y = Math.min(...ys)-pad;
  const ww = Math.max(...xs)-Math.min(...xs)+pad*2, hh = Math.max(...ys)-Math.min(...ys)+pad*2;
  const r = figma.createRectangle();
  r.name = "Hotspot · "+name;
  r.fills = [{type:"SOLID", color:{r:1,g:1,b:1}, opacity:0}];
  screen.appendChild(r);
  r.x = x; r.y = y; r.resize(ww, hh);
  setReaction(r, to);
  return r;
}
