  " Quis autem vel eum iure reprehenderit qui in ea voluptate velit esse quam nihil molestiae."
];
function padTo(textNode, target){
  let w = textNode.characters.split(/\s+/).length;
  let i = 0;
  while (w < target - 2 && i < sentences.length){
    textNode.characters = textNode.characters + sentences[i];
    w = textNode.characters.split(/\s+/).length;
    i++;
  }
  return w;
}
